:root { --dark: #171717; --black: #08080a; --blue: #0099ff; --navy: #00253f; --n50: #fafafa; --n100: #f4f4f5; --n200: #eeeeee; --n300: #e4e4e7; --n600: #4d4d4d; --n700: #444444; --n900: #18181b; --radius: 14px; --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.06), 0 1px 3px rgba(0, 0, 0, 0.06); --shadow-md: 0 6px 24px rgba(0, 0, 0, 0.08); --shadow-lg: 0 24px 60px rgba(0, 0, 0, 0.18); --font: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; --mono: 'JetBrains Mono', ui-monospace, SFMono-Regular, Menlo, monospace; }* { box-sizing: border-box; }html, body { margin: 0px; padding: 0px; font-family: var(--font); color: var(--dark); -webkit-font-smoothing: antialiased; }a { color: inherit; text-decoration: none; }button, input, textarea { font-family: inherit; }.proto-bar { position: fixed; z-index: 900; left: 50%; bottom: 18px; transform: translateX(-50%); display: flex; align-items: center; gap: 14px; padding: 8px 8px 8px 16px; background: rgb(255, 255, 255); border: 1px solid var(--n300); border-radius: 999px; box-shadow: var(--shadow-md); font-size: 12px; color: var(--n600); }.proto-bar strong { color: var(--dark); font-weight: 600; }.proto-bar .dot { width: 6px; height: 6px; border-radius: 50%; background: var(--blue); }.proto-bar a.pb-btn { padding: 6px 12px; border-radius: 999px; background: var(--n100); color: var(--dark); font-weight: 500; }.proto-bar a.pb-btn:hover { background: var(--n200); }.g-page { background: rgb(255, 255, 255); min-height: 100vh; }.g-header { display: flex; align-items: center; gap: 28px; padding: 20px 28px 0px; border-bottom: 1px solid var(--n300); }.g-logo { font-size: 27px; font-weight: 500; letter-spacing: -1px; font-family: Arial, sans-serif; }.g-logo .b { color: rgb(66, 133, 244); }.g-logo .r { color: rgb(234, 67, 53); }.g-logo .y { color: rgb(251, 188, 5); }.g-logo .g { color: rgb(52, 168, 83); }.g-searchbox { display: flex; align-items: center; gap: 12px; flex: 1 1 0%; max-width: 640px; padding: 11px 18px; border: 1px solid var(--n300); border-radius: 999px; box-shadow: var(--shadow-sm); background: rgb(255, 255, 255); font-size: 16px; color: var(--n900); }.g-searchbox .g-icon { color: rgb(154, 160, 166); }.g-tabs { display: flex; gap: 26px; padding: 16px 28px 0px 200px; font-size: 13px; color: rgb(95, 99, 104); }.g-tabs span { padding-bottom: 12px; }.g-tabs span.on { color: rgb(26, 115, 232); border-bottom: 3px solid rgb(26, 115, 232); font-weight: 500; }.g-results { max-width: 700px; padding: 24px 28px 120px 200px; }.g-stats { font-size: 12px; color: rgb(112, 117, 122); margin-bottom: 22px; }.g-result { margin-bottom: 30px; display: block; }.g-result .g-site { display: flex; align-items: center; gap: 10px; margin-bottom: 5px; }.g-result .g-fav { width: 26px; height: 26px; border-radius: 50%; background: var(--dark); color: rgb(255, 255, 255); display: grid; place-items: center; font-size: 11px; font-weight: 700; letter-spacing: -0.5px; }.g-result .g-name { font-size: 14px; color: rgb(32, 33, 36); line-height: 1.2; }.g-result .g-url { font-size: 12px; color: rgb(77, 81, 86); }.g-result h3 { margin: 0px 0px 4px; font-size: 20px; font-weight: 400; color: rgb(26, 13, 171); line-height: 1.3; }.g-result:hover h3 { text-decoration: underline; }.g-result p { margin: 0px; font-size: 14px; line-height: 1.58; color: rgb(77, 81, 86); }.g-result .g-date { color: rgb(112, 117, 122); }.g-sitelinks { display: grid; grid-template-columns: 1fr 1fr; gap: 4px 40px; margin-top: 14px; padding-left: 2px; }.g-sitelinks div { padding: 6px 0px; border-bottom: 1px solid var(--n200); font-size: 14px; color: rgb(26, 13, 171); }.g-hint { display: inline-flex; align-items: center; gap: 8px; margin-left: 10px; padding: 3px 10px; background: rgba(0, 153, 255, 0.1); border: 1px solid rgba(0, 153, 255, 0.35); border-radius: 999px; font-size: 11px; font-weight: 500; color: rgb(0, 114, 194); font-family: var(--font); vertical-align: middle; }.site { background: var(--n50); min-height: 100vh; }.nav { position: sticky; top: 0px; z-index: 50; display: flex; align-items: center; gap: 34px; padding: 16px 40px; background: rgba(250, 250, 250, 0.86); backdrop-filter: blur(12px); border-bottom: 1px solid var(--n300); }.nav .brand { display: flex; align-items: center; gap: 10px; font-weight: 700; font-size: 17px; letter-spacing: -0.4px; }.nav .mark { width: 26px; height: 26px; border-radius: 7px; background: var(--dark); color: rgb(255, 255, 255); display: grid; place-items: center; font-size: 12px; font-weight: 800; }.nav .links { display: flex; gap: 26px; font-size: 14px; color: var(--n600); }.nav .links a:hover { color: var(--dark); }.nav .spacer { flex: 1 1 0%; }.btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; padding: 12px 22px; border-radius: 10px; font-size: 14px; font-weight: 600; line-height: 1; border: 1px solid transparent; cursor: pointer; transition: transform 0.12s, background 0.15s; }.btn:active { transform: translateY(1px); }.btn-dark { background: var(--dark); color: rgb(255, 255, 255); }.btn-dark:hover { background: rgb(0, 0, 0); }.btn-ghost { background: rgb(255, 255, 255); color: var(--dark); border-color: var(--n300); }.btn-ghost:hover { background: var(--n100); }.btn-blue { background: var(--blue); color: rgb(255, 255, 255); }.hero { max-width: 1120px; margin: 0px auto; padding: 96px 40px 40px; text-align: center; }.eyebrow { display: inline-flex; align-items: center; gap: 8px; padding: 6px 14px; margin-bottom: 26px; background: rgb(255, 255, 255); border: 1px solid var(--n300); border-radius: 999px; font-size: 12px; font-weight: 500; color: var(--n600); }.eyebrow .pip { width: 6px; height: 6px; border-radius: 50%; background: var(--blue); }.hero h1 { margin: 0px 0px 20px; font-size: 62px; line-height: 1.05; font-weight: 800; letter-spacing: -2.4px; }.hero p.lede { margin: 0px auto; max-width: 620px; font-size: 19px; line-height: 1.55; color: var(--n600); }.fork { display: grid; grid-template-columns: 1fr 1fr; gap: 22px; max-width: 1000px; margin: 56px auto 0px; padding: 0px 40px 120px; }.fork-card { display: flex; flex-direction: column; gap: 14px; padding: 30px; text-align: left; background: rgb(255, 255, 255); border-radius: 18px; box-shadow: var(--shadow-sm); transition: box-shadow 0.18s, transform 0.18s; }.fork-card:hover { box-shadow: var(--shadow-md); transform: translateY(-3px); }.rows { max-width: 1180px; margin: 0px auto; padding: 56px 40px 130px; }.rows h1 { margin: 0px 0px 12px; font-size: 52px; line-height: 1.05; font-weight: 800; letter-spacing: -2px; }.rows .rows-note { max-width: none; margin: 0px 0px 48px; text-align: left; }.site .nav-pad-btn { display: inline-flex; align-items: center; height: 32px; padding: 0px 12px; border: 1px solid var(--ds-gray-400, #e5e5e5); border-radius: 6px; background: rgb(255, 255, 255); font-family: 'Geist', var(--font); font-size: 14px; font-weight: 500; line-height: 20px; color: var(--ds-gray-1000, #171717); transition: background 0.15s, border-color 0.15s; }.site .nav-pad-btn:hover { background: rgb(250, 250, 250); border-color: rgb(212, 212, 212); }.rows.pad { --ds-background-100: #ffffff; --ds-background-200: #fafafa; --ds-gray-100: #fafafa; --ds-gray-200: #f5f5f5; --ds-gray-300: #eaeaea; --ds-gray-400: #e5e5e5; --ds-gray-500: #d4d4d4; --ds-gray-900: #666666; --ds-gray-1000: #171717; --ds-green-100: #effbf3; --ds-green-900: #067a41; --ds-blue-100: #f0f7ff; --ds-blue-900: #0070f3; padding-top: 40px; padding-bottom: 80px; font-family: 'Geist', var(--font); color: var(--ds-gray-1000); }.pad-intro { margin: 0px 0px 20px; }.rows.pad .pad-intro h1 { margin: 0px; font-size: 32px; font-weight: 600; line-height: 40px; letter-spacing: -0.02em; }.pad-list { display: flex; flex-direction: column; gap: 8px; margin: 0px; padding: 0px; list-style: none; }.pad-section { border: 1px solid var(--ds-gray-400); border-radius: 6px; overflow: hidden; background: var(--ds-background-100); }.pad-toggle { display: flex; align-items: center; justify-content: space-between; gap: 12px; width: 100%; padding: 10px 12px; border: 0px; margin: 0px; background: var(--ds-background-100); font: inherit; color: inherit; text-align: left; cursor: pointer; transition: background 0.15s; }.pad-toggle:hover { background: var(--ds-gray-100); }.pad-toggle[aria-expanded="true"] { background: var(--ds-background-100); border-bottom: 1px solid var(--ds-gray-400); }.pad-toggle-text { display: flex; align-items: center; flex-wrap: wrap; gap: 8px; min-width: 0px; }.pad-toggle-title { font-size: 14px; font-weight: 500; line-height: 20px; letter-spacing: -0.01em; }.pad-toggle-title code { font-family: 'Geist Mono', var(--mono); font-size: 13px; font-weight: 500; }.pad-chevron { flex-shrink: 0; width: 16px; height: 16px; color: var(--ds-gray-900); transition: transform 0.15s; }.pad-chevron svg { display: block; width: 16px; height: 16px; }.pad-toggle[aria-expanded="true"] .pad-chevron { transform: rotate(180deg); }.pad-panel { padding: 4px; }.pad-entries { display: flex; flex-direction: column; gap: 2px; margin: 0px; padding: 0px; list-style: none; }.pad-entry { display: flex; align-items: center; gap: 8px; min-height: 36px; padding: 0px 10px; border-radius: 4px; font-size: 14px; font-weight: 500; line-height: 20px; letter-spacing: -0.01em; color: var(--ds-gray-1000); transition: background 0.15s; }.pad-entry-text { flex: 1 1 0%; min-width: 0px; }.pad-entry .pad-badge { flex-shrink: 0; margin-left: auto; }.pad-entry:hover { background: var(--ds-gray-200); }.pad-entry code { font-family: 'Geist Mono', var(--mono); font-size: 13px; font-weight: 500; }.pad-badge { display: inline-flex; align-items: center; height: 20px; padding: 0px 6px; border-radius: 999px; font-size: 12px; font-weight: 500; line-height: 16px; letter-spacing: 0px; white-space: nowrap; }.pad-badge--green { background: var(--ds-green-100); color: var(--ds-green-900); }.pad-badge--gray { background: var(--ds-gray-200); color: var(--ds-gray-900); }.pad-badge--blue { background: var(--ds-blue-100); color: var(--ds-blue-900); }.pad-subgroup { padding: 8px 4px 4px; }.pad-subgroup + .pad-subgroup { border-top: 1px solid var(--ds-gray-400); margin-top: 4px; padding-top: 12px; }.pad-subgroup-title { margin: 0px 0px 2px; padding: 0px 10px; font-size: 12px; font-weight: 600; line-height: 16px; color: var(--ds-gray-1000); letter-spacing: -0.01em; }.pad-subgroup-note { margin: 0px 0px 6px; padding: 0px 10px; font-size: 12px; font-weight: 400; line-height: 16px; color: var(--ds-gray-900); }.pad-tabs { display: inline-flex; align-self: flex-start; width: fit-content; max-width: 100%; gap: 4px; margin: 4px 4px 8px; padding: 3px; background: var(--ds-gray-100); border-radius: 8px; }.pad-tab { padding: 6px 12px; border: 0px; border-radius: 6px; background: transparent; font-style: inherit; font-variant: inherit; font-stretch: inherit; line-height: inherit; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; font-size: 13px; font-weight: 500; color: var(--ds-gray-900); cursor: pointer; white-space: nowrap; }.pad-tab.on { background: var(--ds-background-100); color: var(--ds-gray-1000); box-shadow: rgba(0, 0, 0, 0.06) 0px 1px 2px; }.pad-tab-panel[hidden] { display: none; }.pad-empty { margin: 0px; padding: 16px 10px 12px; font-size: 13px; font-weight: 400; line-height: 20px; color: var(--ds-gray-900); }.pad-note { margin: 12px 10px 4px; font-size: 12px; line-height: 18px; color: rgb(113, 113, 122); }.pad-note code { padding: 1px 5px; border-radius: 4px; background: rgb(244, 244, 245); font-family: "Geist Mono", ui-monospace, monospace; font-size: 11px; }.pad-tab-panel:not(.is-empty) .pad-empty { display: none; }.pad-tab-panel.is-empty .pad-entries { display: none; }.rows > .row { margin-bottom: 52px; }.row-title { display: inline-flex; align-items: baseline; gap: 9px; margin: 0px 0px 18px; font-size: 22px; font-weight: 700; letter-spacing: -0.6px; }.row-title .arrow { font-size: 17px; color: rgb(161, 161, 170); transition: transform 0.18s, color 0.18s; }a.row-title:hover .arrow { transform: translateX(4px); color: var(--dark); }.fork-card h2 .badge, .row-title .badge { padding: 3px 9px; border: 1px solid rgb(212, 212, 216); border-radius: 999px; font-size: 11px; font-weight: 500; letter-spacing: 0px; color: rgb(82, 82, 91); white-space: nowrap; }.row-title .badge.done, .fork-card h2 .badge.done { border-color: rgb(207, 230, 216); background: rgb(241, 248, 244); color: rgb(31, 107, 69); }.fork-card h2 .badge { vertical-align: middle; margin-left: 8px; letter-spacing: 0px; }.row-cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 22px; align-items: stretch; }.row-cards.two-up { grid-template-columns: repeat(2, 1fr); }.row-cards.one-up { grid-template-columns: min(620px, 100%); }.fork-card h2 { margin: 0px; font-size: 24px; letter-spacing: -0.7px; }.fork-card p { margin: 0px; font-size: 15px; line-height: 1.6; color: var(--n600); }.fork-card ul { margin: 4px 0px 0px; padding-left: 18px; font-size: 14px; line-height: 1.9; color: var(--n600); }.fork-card .go { margin-top: auto; padding-top: 18px; }.eai-nav { background: rgb(255, 255, 255); padding: 18px 34px; border-bottom: 1px solid var(--n200); }.eai-nav .wordmark { height: 15px; display: block; }.eai-nav .links { gap: 22px; font-size: 14px; white-space: nowrap; }.eai-nav .lnk-login { font-size: 14px; color: var(--dark); margin-right: 14px; white-space: nowrap; }.eai-nav .btn-sm { white-space: nowrap; }.btn-sm { padding: 9px 18px; font-size: 13px; border-radius: 8px; }.btn-lg { height: 54px; padding: 0px 26px; font-size: 16px; border-radius: 10px; }.eai-hero { max-width: 1180px; margin: 0px auto; padding: 60px 56px 130px; }.eai-hero h1 { margin: 0px 0px 18px; font-size: 44px; line-height: 1.15; font-weight: 800; letter-spacing: -1.4px; }.eai-hero p.lede { margin: 0px 0px 38px; max-width: 620px; font-size: 27px; line-height: 1.32; color: rgb(107, 114, 128); font-weight: 400; }.start-row { display: flex; align-items: stretch; gap: 14px; flex-wrap: wrap; padding: 6px; margin: 0px -6px; border-radius: 14px; }.start-row.flash { animation: 1.4s ease 0s 1 normal none running flash; }@keyframes flash { 
