}.cmd-field { display: flex; align-items: center; gap: 10px; min-width: 330px; height: 54px; padding: 0px 18px; background: rgb(255, 255, 255); border: 2px solid var(--dark); border-radius: 10px; cursor: pointer; text-align: left; font-family: var(--mono); font-size: 16px; color: var(--dark); }.cmd-field .pfx { color: rgb(154, 160, 166); }.cmd-field .cmd { flex: 1 1 0%; }.cmd-field .hint-copy { font-family: var(--font); font-size: 11px; font-weight: 600; letter-spacing: 0.6px; text-transform: uppercase; color: rgb(154, 160, 166); }.cmd-field:hover { background: var(--n50); }.cmd-field.copied { border-color: var(--blue); }.cmd-field.copied .hint-copy { color: var(--blue); }.start-note { margin-top: 16px; font-size: 13px; color: var(--n600); }.start-note strong { color: var(--dark); }.start-next { display: none; margin-top: 20px; }.start-next.on { display: block; }.shot { margin-top: 54px; border: 1px solid var(--n300); border-radius: 14px; overflow: hidden; box-shadow: var(--shadow-md); background: rgb(255, 255, 255); }.shot-bar { display: flex; align-items: center; gap: 8px; padding: 10px 14px; background: var(--n100); border-bottom: 1px solid var(--n300); }.shot-bar .tl { width: 10px; height: 10px; border-radius: 50%; }.shot-bar .tl.r { background: rgb(255, 95, 87); }.shot-bar .tl.y { background: rgb(254, 188, 46); }.shot-bar .tl.g { background: rgb(40, 200, 64); }.shot-bar .shot-url { margin-left: 12px; font-size: 11px; color: var(--n600); }.shot-tabs { display: flex; justify-content: center; gap: 30px; padding: 13px; border-bottom: 1px solid var(--n200); font-size: 12px; color: var(--n600); }.shot-tabs .on { color: var(--dark); font-weight: 600; }.shot-tabs .off { color: rgb(195, 198, 204); }.shot-cols { display: grid; grid-template-columns: 1fr 1.5fr 1fr; gap: 14px; padding: 16px; background: var(--n50); }.shot-card { padding: 14px; background: rgb(255, 255, 255); border: 1px solid var(--n300); border-radius: 10px; font-size: 11px; color: var(--n600); }.shot-card .t { font-size: 13px; font-weight: 600; color: var(--dark); margin-bottom: 4px; }.shot-card .sub { margin-bottom: 12px; }.shot-card .map { height: 88px; margin: 10px 0px; border-radius: 6px; background: linear-gradient(135deg, rgb(232, 238, 245), rgb(219, 230, 240) 60%, rgb(238, 242, 246)); }.shot-card .tags { display: flex; gap: 6px; margin-bottom: 12px; }.shot-card .tags span { flex: 1 1 0%; padding: 8px 4px; text-align: center; border: 1px solid var(--n300); border-radius: 6px; font-size: 10px; }.shot-card .kv { padding: 5px 0px; border-top: 1px solid var(--n200); }.shot-card .kv b { display: block; font-size: 9px; text-transform: uppercase; letter-spacing: 0.5px; color: rgb(154, 160, 166); font-weight: 500; }.shot-card .row { display: flex; align-items: center; gap: 10px; padding: 9px 0px; border-top: 1px solid var(--n200); }.shot-card .row span { flex: 1 1 0%; color: var(--dark); }.shot-card .row i { font-style: normal; padding: 2px 8px; border-radius: 999px; font-size: 9px; font-weight: 600; }.shot-card .row i.pass { background: rgb(220, 252, 231); color: rgb(22, 101, 52); }.shot-card .row i.rev { background: var(--n100); color: var(--n600); }.shot-card .bub { padding: 10px; background: var(--n100); border-radius: 8px; line-height: 1.5; margin-bottom: 10px; }.shot-card .q { padding: 9px; border: 1px solid var(--n300); border-radius: 8px; margin-bottom: 8px; line-height: 1.45; }.cli-page { background: var(--n100); }.cli-hero { max-width: 1000px; margin: 0px auto; padding: 90px 40px 0px; text-align: center; }.cli-hero h1 { margin: 0px 0px 22px; font-size: 68px; line-height: 1.02; font-weight: 800; letter-spacing: -3px; }.cli-hero p.lede { margin: 0px auto 40px; max-width: 640px; font-size: 20px; line-height: 1.5; color: var(--n600); }.cta-row { display: flex; justify-content: center; align-items: stretch; gap: 16px; flex-wrap: wrap; }.copy-pill { display: inline-flex; align-items: center; gap: 16px; padding: 0px 8px 0px 26px; height: 62px; background: var(--dark); color: rgb(255, 255, 255); border-width: medium; border-style: none; border-color: currentcolor; border-image: none; border-radius: 14px; cursor: pointer; font-family: var(--mono); font-size: 19px; font-weight: 500; box-shadow: var(--shadow-md); transition: transform 0.12s, background 0.15s; }.copy-pill:hover { background: rgb(0, 0, 0); }.copy-pill:active { transform: translateY(1px); }.copy-pill .cmd { white-space: nowrap; }.copy-pill .copy-chip { padding: 10px 16px; border-radius: 10px; background: rgba(255, 255, 255, 0.16); color: rgb(255, 255, 255); font-family: var(--font); font-size: 12px; font-weight: 700; letter-spacing: 1px; min-width: 84px; text-align: center; }.copy-pill.copied .copy-chip { background: var(--blue); }.btn-docs { height: 62px; padding: 0px 30px; font-size: 17px; border-radius: 14px; background: rgb(255, 255, 255); border: 1px solid var(--n300); }.copy-note { margin-top: 18px; font-size: 13px; color: var(--n600); min-height: 20px; }.copy-note strong { color: var(--dark); }.steps-strip { display: flex; justify-content: center; gap: 8px; flex-wrap: wrap; margin: 46px 0px 0px; font-size: 13px; color: var(--n600); }.steps-strip span { display: inline-flex; align-items: center; gap: 8px; padding: 7px 14px; background: rgb(255, 255, 255); border: 1px solid var(--n300); border-radius: 999px; }.steps-strip b { display: grid; place-items: center; width: 18px; height: 18px; border-radius: 50%; background: var(--dark); color: rgb(255, 255, 255); font-size: 10px; }.term { background: rgb(18, 20, 26); border-radius: 14px; overflow: hidden; box-shadow: var(--shadow-lg); border: 1px solid rgb(35, 38, 47); display: flex; flex-direction: column; }.term-bar { display: flex; align-items: center; gap: 8px; padding: 12px 16px; background: rgb(27, 30, 38); border-bottom: 1px solid rgb(38, 42, 52); }.term-bar .tl { width: 11px; height: 11px; border-radius: 50%; }.term-bar .tl.r { background: rgb(255, 95, 87); }.term-bar .tl.y { background: rgb(254, 188, 46); 